import {apiClient} from '@common/http/query-client';
import {DashboardLayout} from '@common/ui/dashboard/dashboard-layout';
import {Badge} from '@shadcn/badge/badge';
import {Button} from '@shadcn/button/button';
import {Card} from '@shadcn/card/card';
import {Dialog} from '@shadcn/dialog/dialog';
import {Field} from '@shadcn/forms/field';
import {Textarea} from '@shadcn/forms/textarea/textarea';
import {Table} from '@shadcn/table/table';
import {Trans} from '@ui/i18n/trans';
import {CheckIcon, EyeIcon, FileIcon, ShieldCheckIcon, XIcon} from 'lucide-react';
import {useCallback, useEffect, useState} from 'react';
import {Link} from 'react-router';

type Product = {id: number; title: string; description?: string | null; price_cents: number; currency: string; status: string; rejection_reason?: string | null; creator?: {name: string; email: string}; cover?: {url: string} | null; files?: Array<{id: number; name: string}>; biolinks?: Array<{name: string}>};

export function Component() {
  const [products, setProducts] = useState<Product[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string>();
  const [selected, setSelected] = useState<Product>();
  const [reason, setReason] = useState('');
  const [saving, setSaving] = useState(false);
  const load = useCallback(async () => { setLoading(true); try { const response = await fetch('/api/v1/admin/digital-products?status=pending_approval', {credentials: 'same-origin', headers: {Accept: 'application/json'}}); if (!response.ok) throw new Error('Unable to load pending digital products.'); const payload = await response.json(); setProducts(payload.data ?? []); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Unable to load pending digital products.'); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  const approve = async (product: Product) => { setSaving(true); try { await apiClient.post(`/api/v1/admin/digital-products/${product.id}/approve`); setSelected(undefined); await load(); } catch { setError('Unable to approve product.'); } finally { setSaving(false); } };
  const reject = async () => { if (!selected) return; setSaving(true); try { await apiClient.post(`/api/v1/admin/digital-products/${selected.id}/reject`, {reason: reason.trim() || null}); setSelected(undefined); setReason(''); await load(); } catch { setError('Unable to reject product.'); } finally { setSaving(false); } };
  return <DashboardLayout.MainSection><DashboardLayout.SectionHeader><DashboardLayout.SidebarToggle /><div><DashboardLayout.SectionTitle><Trans message="Digital Products" /></DashboardLayout.SectionTitle><p className="mt-0.5 text-sm text-muted-foreground"><Trans message="Review creator products before they can be sold on bio pages." /></p></div><Button variant="outline" render={<Link to="/admin/digital-products/payouts" />}><Trans message="Payout requests" /></Button></DashboardLayout.SectionHeader><DashboardLayout.SectionContent className="overflow-y-auto"><div className="mx-auto w-full max-w-6xl py-6">{error && <div className="mb-5 rounded-input border border-destructive/40 bg-destructive/5 p-3 text-sm text-destructive">{error}</div>}<Card.Root><Card.Header><Card.Title><Trans message="Pending review" /></Card.Title><Card.Description><Trans message="Only approved products can appear publicly or start checkout." /></Card.Description></Card.Header><Card.Content className="overflow-x-auto"><Table.Root><Table.Header><Table.Row><Table.Head><Trans message="Product" /></Table.Head><Table.Head><Trans message="Creator" /></Table.Head><Table.Head><Trans message="Price" /></Table.Head><Table.Head className="text-end"><Trans message="Actions" /></Table.Head></Table.Row></Table.Header><Table.Body>{loading ? <Table.Row><Table.Cell colSpan={4} className="h-28 text-center text-muted-foreground"><Trans message="Loading…" /></Table.Cell></Table.Row> : products.length ? products.map(product => <Table.Row key={product.id}><Table.Cell><div className="flex items-center gap-3">{product.cover?.url ? <img className="size-10 rounded-input object-cover" src={product.cover.url} alt="" /> : <div className="flex size-10 items-center justify-center rounded-input bg-muted"><FileIcon className="size-4" /></div>}<div><p className="font-medium">{product.title}</p><p className="text-xs text-muted-foreground"><Trans message=":count files • :count pages" values={{count: product.files?.length ?? 0}} /></p></div></div></Table.Cell><Table.Cell><p className="text-sm">{product.creator?.name}</p><p className="text-xs text-muted-foreground">{product.creator?.email}</p></Table.Cell><Table.Cell>{formatMoney(product.price_cents, product.currency)}</Table.Cell><Table.Cell><div className="flex justify-end gap-2"><Button size="sm" variant="outline" onClick={() => setSelected(product)}><EyeIcon /><Trans message="Review" /></Button><Button size="sm" onClick={() => void approve(product)}><CheckIcon /><Trans message="Approve" /></Button></div></Table.Cell></Table.Row>) : <Table.Row><Table.Cell colSpan={4} className="h-32 text-center text-muted-foreground"><Trans message="No products are waiting for review." /></Table.Cell></Table.Row>}</Table.Body></Table.Root></Card.Content></Card.Root></div></DashboardLayout.SectionContent>{selected && <Dialog.Root open onOpenChange={open => !open && setSelected(undefined)}><Dialog.Portal><Dialog.Backdrop /><Dialog.Content className="sm:max-w-lg"><Dialog.Header><Dialog.Title><ShieldCheckIcon /><Trans message="Review digital product" /></Dialog.Title></Dialog.Header><Dialog.Body><div className="space-y-4"><div><p className="font-semibold">{selected.title}</p><p className="mt-1 whitespace-pre-wrap text-sm text-muted-foreground">{selected.description}</p></div><div className="rounded-input bg-muted p-3 text-sm"><p><Trans message="Creator: :name" values={{name: selected.creator?.name ?? '—'}} /></p><p className="mt-1"><Trans message="Files: :count" values={{count: selected.files?.length ?? 0}} /></p></div><Field.Root><Field.Label><Trans message="Rejection reason (optional)" /></Field.Label><Textarea rows={4} value={reason} onChange={e => setReason(e.target.value)} placeholder="Explain what the creator should change." /></Field.Root></div></Dialog.Body><Dialog.Footer><Button color="danger" variant="outline" disabled={saving} onClick={() => void reject()}><XIcon /><Trans message="Reject" /></Button><Button disabled={saving} onClick={() => void approve(selected)}><CheckIcon /><Trans message="Approve" /></Button></Dialog.Footer></Dialog.Content></Dialog.Portal></Dialog.Root>}</DashboardLayout.MainSection>;
}
function formatMoney(cents: number, currency: string) { return new Intl.NumberFormat(undefined, {style: 'currency', currency}).format(cents / 100); }
